-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in Portuguese (Brazil) words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	["Succubus and Incubus (Horde)"] = "Súcubo e Íncubo (Horda)",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "No nível 20: o súcubo e o íncubo do Forever, seu gêmeo masculino, cada um com uma bolsa de almas para seus fragmentos.",

	-- Step 1: Devourer of Souls (Orgrimmar)
	-- {npc:5875} Gan'rul Bloodeye · {object:172960} Cleft of Shadow (no name in this language: may be words) · {object:172982} Valley of Strength (no name in this language: may be words) · {npc:5909} Cazul · {npc:5675} Carendin Halgar · {zone:1458} Undercity · {quest:1472} Devourer of Souls · {zone:1454} Orgrimmar
	["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "No nível 20, {npc:5875}, na {object:172960} sob o {object:172982}, envia você a {npc:5909}, a poucos passos. Dois instrutores iniciam esses demônios, {npc:5875} aqui e {npc:5675} na {zone:1458}, e você só pode pegar um; este guia segue a {quest:1472} que você pegou. {npc:5909} oferece os dois ramos de {zone:1454}: pegue os dois.",
	["the succubus"] = "o súcubo",
	["the incubus"] = "o íncubo",

	-- Step 2: Zankaja
	-- {npc:5910} Zankaja · {object:172982} Valley of Strength (no name in this language: may be words)
	["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads."] = "{npc:5910} mora numa cabana nos penhascos do lado oeste da cidade, acima do {object:172982}: suba a torre de mantícoras, atravesse a ponte no alto dela para o oeste e vire à direita saindo dela. Ela manda você para a Encruzilhada.",

	-- Step 3: Magar
	-- {npc:3363} Magar · {object:173018} Magar's Cloth Goods (no name in this language: may be words) · {object:172960} Cleft of Shadow (no name in this language: may be words) · {zone:1440} Ashenvale
	["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} cuida de {object:173018}, a leste da {object:172960}, na rua principal. Ele pede que você procure sua companheira, Krilge, em {zone:1440}.",

	-- Step 4: Gazrog
	-- {npc:3464} Gazrog · {npc:4197} Ken'zigla · {area:2539} Malaka'jin · {zone:1442} Stonetalon Mountains
	["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464} espera na frente da estalagem na Encruzilhada. Ele manda você a {npc:4197} em {area:2539}, em {zone:1442}.",

	-- Step 5: Ken'zigla
	-- {zone:1442} Stonetalon Mountains · {area:2539} Malaka'jin · {npc:4197} Ken'zigla · {npc:5911} Grunt Logmar
	["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "Siga a estrada para o oeste da Encruzilhada até {zone:1442} e, logo depois da divisa, a trilha fraca que sobe à esquerda (sul): {area:2539} não pode ser alcançada pela estrada principal. {npc:4197} entrega a você a poção dela para {npc:5911}.",

	-- Step 6: Grunt Dogran
	-- {npc:5911} Grunt Logmar · {area:378} Camp Taurajo · {npc:5875} Gan'rul Bloodeye
	["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911} fica em {area:378}, ao sul pela estrada saindo da Encruzilhada. Ele manda você ao norte, ao acampamento de quilboar onde Dogran é mantido: o acampamento com duas cabanas lado a lado, a noroeste de um acampamento falso cujas cabanas ficam separadas. Um quilboar raro elite de nível 22 às vezes guarda as cabanas: mande seu emissário do caos entrar, sacrifique-o se precisar e fale com Dogran. Ele dá a você um pingente para {npc:5875}. Guarde-o.",

	-- Step 7: The Binding: succubus (Orgrimmar)
	-- {quest:1513} The Binding · {zone:1454} Orgrimmar
	["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}: súcubo ({zone:1454})",
