	-- ["{area:422} lies in southern {zone:1440}, south of {area:431}. The Shadethicket bog beasts around the lake drop the {item:190232}, about one in twenty."] = "{area:422} fica no sul de {zone:1440}, ao sul do {area:431}. As feras do pântano Umbrárvore em volta do lago soltam o {item:190232}, cerca de uma vez em vinte.",
	-- ["{npc:185333} works as a tailor for the {area:279} wizards at {area:233}, in eastern {zone:1421}. Take her heart."] = "{npc:185333} trabalha como alfaiate para os teurgos de {area:279} em {area:233}, no leste da {zone:1421}. Pegue o coração dela.",
	-- ["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and ride or fly on to {area:392}."] = "{npc:185334} trabalha em {area:392}, no litoral dos {zone:1413}. Pegue o zepelim para {zone:1411} e siga montado ou voando até {area:392}.",
